const cfg = $('Config').first().json;
const runMode = String(cfg.run_mode || 'both').trim().toLowerCase();
const parsedMax = parseInt(cfg.max_leads, 10);
const rawMax = Number.isFinite(parsedMax) && parsedMax > 0 ? parsedMax : 25;
const clampedNewMax = Math.min(rawMax, 2000);
const HARD_BATCH_CAP = 2000;
const clampNote = rawMax > 2000 ? ` (Clamped from ${rawMax} to 2,000 max safety limit)` : '';

const normalizeDomain = (url) => String(url || '').trim().toLowerCase().replace(/^https?:\/\/(www\.)?/, '').split(/[/?#:]/)[0];
const socialBlocked = [
  'facebook.com', 'instagram.com', 'yelp.com', 'linktr.ee', 'tiktok.com',
  'google.com', 'goo.gl', 'squareup.com', 'vagaro.com', 'heygoldie.com', 'skinclique.com'
];
const isBlockedDomain = (dom) => socialBlocked.some(b => dom === b || dom.endsWith('.' + b));
const hasRealValue = (v) => Boolean(v && String(v).trim() !== '' && String(v).trim() !== 'None');

const seenDomains = new Set();
const sheetDomains = new Set();
const queuedExistingDomains = new Set();
const validLeads = [];
const sheetLeadMap = {};
let skippedExisting = 0;
let existingQueuedCount = 0;
let newMapsQueuedCount = 0;

// 1. Queue un-enriched rows from Google Sheet (and group multi-location sheet chains by domain)
const existingRows = $('Fetch Existing Sheets Leads').all();
for (const row of existingRows) {
  const r = row.json || {};
  const rawWeb = String(r.Website || r.website || r.Domain || r.domain || '').trim();
  if (!rawWeb) continue;

  const webUrl = rawWeb.startsWith('http') ? rawWeb : `https://${rawWeb}`;
  const dom = normalizeDomain(webUrl);
  if (!dom || !dom.includes('.') || isBlockedDomain(dom)) continue;

  // Only treat as enriched if an actual contact/enrichment field was found (not fallback Intent_Tier/Icebreaker)
  const isAlreadyEnriched = Boolean(
  (r.Verified_Email && String(r.Verified_Email).includes('@')) ||
  hasRealValue(r.Decision_Maker) ||
  hasRealValue(r.LinkedIn_Profile) ||
  hasRealValue(r.Contact_Form_URL) ||
  hasRealValue(r.Instagram_URL) ||
  (!cfg.retry_empty_leads && (hasRealValue(r.Intent_Tier) || hasRealValue(r.Cold_Email_Icebreaker)))
);

  seenDomains.add(dom);
  sheetDomains.add(dom);
  if (isAlreadyEnriched || runMode === 'scrape_new') {
    continue;
  }

  const rowTitle = String(r.Company_Name || r.Company || r.title || r.name || '').trim();
  const rowCity = String(r.city || (r.City_State || '').split(',')[0] || '').trim();
  const rowState = String(r.state || (r.City_State || '').split(',')[1] || '').trim();
  const rowCityState = String(r.City_State || [rowCity, rowState].filter(Boolean).join(', ') || '').trim();
  const rowPhone = String(r.Phone || r.phone || '').trim();

  if (!sheetLeadMap[dom]) sheetLeadMap[dom] = [];
  sheetLeadMap[dom].push({
    originalWebsite: rawWeb,
    Company_Name: rowTitle,
    Phone: rowPhone,
    City_State: rowCityState
  });

  if (!queuedExistingDomains.has(dom) && validLeads.length < HARD_BATCH_CAP) {
    queuedExistingDomains.add(dom);
    validLeads.push({
      website: webUrl,
      title: rowTitle,
      city: rowCity,
      state: rowState,
      phone: rowPhone
    });
    existingQueuedCount++;
  }
}

const suppressedPreCount = seenDomains.size - existingQueuedCount;

// 2. In 'scrape_new' or 'both' mode, add up to clampedNewMax NEW Google Maps leads on top
const mapsItems = (runMode !== 'enrich_existing' && $('Filter: Has Website?').isExecuted)
  ? $('Filter: Has Website?').all()
  : [];

if (runMode !== 'enrich_existing') {
  for (const item of mapsItems) {
    if (newMapsQueuedCount >= clampedNewMax || validLeads.length >= HARD_BATCH_CAP) break;
    const d = item.json || {};
    const web = String(d.website || '').trim();
    if (!web || !web.startsWith('http')) continue;
    const dom = normalizeDomain(web);
    if (!dom || !dom.includes('.') || isBlockedDomain(dom)) continue;

    const mTitle = String(d.title || d.name || '').trim();
    const mPhone = String(d.phone || d.phoneUnformatted || '').trim();
    const mCityState = [d.city, d.state].filter(Boolean).join(', ');

    if (seenDomains.has(dom)) {
      // Only fan out multi-location branches if the domain came from Maps in this run (never add ghost URLs to existing sheet domains)
      if (!sheetDomains.has(dom) && sheetLeadMap[dom] && !sheetLeadMap[dom].some(x => x.Phone === mPhone && x.Company_Name === mTitle)) {
        sheetLeadMap[dom].push({
          originalWebsite: web,
          Company_Name: mTitle,
          Phone: mPhone,
          City_State: mCityState
        });
      } else {
        skippedExisting++;
      }
      continue;
    }

    seenDomains.add(dom);
    sheetLeadMap[dom] = [{
      originalWebsite: web,
      Company_Name: mTitle,
      Phone: mPhone,
      City_State: mCityState
    }];
    validLeads.push({
      website: web,
      title: mTitle,
      city: d.city || '',
      state: d.state || '',
      phone: mPhone
    });
    newMapsQueuedCount++;
  }
}

return [{
  json: {
    leads: validLeads,
    maxLeads: validLeads.length,
    existingQueuedCount,
    newMapsQueuedCount,
    skippedExisting,
    suppressedPreCount,
    sheetLeadMap,
    runMode,
    clampedMax: clampedNewMax,
    clampNote,
    mapsRawCount: mapsItems.length,
    clientLedger: cfg.clientLedger || 'weekly_gmaps_master'
  }
}];

const batchMeta = $('Filter, Clamp, & Suppress existing domains').first().json;
const cfg = $('Config').first().json;
const sheetMap = batchMeta.sheetLeadMap || {};
const normalizeDomain = (url) => String(url || '').trim().toLowerCase().replace(/^https?:\/\/(www\.)?/, '').split(/[/?#:]/)[0];
const items = $input.all().map(i => i.json).filter(r => r && (r.Company_Name || r.Website));

const AD_SIGNALS = ['Meta Pixel', 'Google Ads', 'TikTok Pixel'];
const seen = new Set();
const deduped = [];

for (const r of items) {
  const dom = normalizeDomain(r.Website || '');
  if (!dom || dom === 'google.com' || !sheetMap[dom]) continue;

  const rawEntry = sheetMap[dom];
  const locations = Array.isArray(rawEntry) && rawEntry.length > 0
    ? rawEntry
    : [rawEntry];

  const cleanEmail = (r.Verified_Email && r.Verified_Email !== 'None') ? r.Verified_Email : '';
  const cleanEmailType = (cleanEmail && r.Email_Type && r.Email_Type !== 'None') ? r.Email_Type : '';
  const pixels = (r.Ad_Pixels && r.Ad_Pixels !== 'None') ? r.Ad_Pixels : 'None Detected';

  const matchedAds = AD_SIGNALS.filter(sig => pixels.toLowerCase().includes(sig.toLowerCase()));
  const hasAds = matchedAds.length > 0;
  const adSummary = matchedAds.join(' & ');
  const intentTier = hasAds ? '🔥 High Intent (Running Ads)' : 'Standard Outbound';

  const rawDm = (r.Decision_Maker && r.Decision_Maker !== 'None')
    ? String(r.Decision_Maker).replace(/^(?:Dr\.?|Mr\.?|Ms\.?|Mrs\.?)\s+/i, '').trim()
    : '';
  const dmName = rawDm ? rawDm.split(/\s+/)[0] : 'there';

  for (const sheetOrig of locations) {
    const finalWebsite = sheetOrig.originalWebsite || r.Website || '';
    const key = `${finalWebsite.toLowerCase()}|${(sheetOrig.Company_Name || '').toLowerCase()}|${sheetOrig.Phone || ''}|${cleanEmail.toLowerCase()}`;
    if (seen.has(key)) continue;
    seen.add(key);

    const companyName = sheetOrig.Company_Name || r.Company_Name || '';
    const cityState = sheetOrig.City_State || cfg['location (city; state)'] || r.City_State || '';
    const phone = sheetOrig.Phone || r.Phone || '';
    const defaultHook = hasAds
      ? `Hi ${dmName}, saw ${companyName || 'your team'} is actively running ${adSummary} campaigns in ${cityState} and wanted to reach out.`
      : `Hi ${dmName}, came across ${companyName || 'your practice'} in ${cityState} while researching top ${cfg.category} providers.`;

    deduped.push({
      json: {
        Company_Name: companyName,
        Decision_Maker: (r.Decision_Maker && r.Decision_Maker !== 'None') ? r.Decision_Maker : '',
        Job_Title: (r.Job_Title && r.Job_Title !== 'None') ? r.Job_Title : '',
        Verified_Email: cleanEmail,
        Email_Type: cleanEmailType,
        Phone: phone,
        LinkedIn_Profile: (r.LinkedIn_Profile && r.LinkedIn_Profile !== 'None') ? r.LinkedIn_Profile : '',
        Website: finalWebsite,
        City_State: cityState,
        Ad_Pixels: pixels,
        Intent_Tier: intentTier,
        Cold_Email_Icebreaker: defaultHook,
        Contact_Form_URL: (r.Contact_Form_URL && r.Contact_Form_URL !== 'None') ? r.Contact_Form_URL : '',
        Instagram_URL: (r.Instagram_URL && r.Instagram_URL !== 'None') ? r.Instagram_URL : ''
      }
    });
  }
}

if (deduped.length === 0) {
  return [{
    json: {
      _isEmpty: true,
      summaryText: `⚠️ Weekly Lead Run [mode=${batchMeta.runMode}]: 0 leads returned (existing queued: ${batchMeta.existingQueuedCount || 0}, new Maps queued: ${batchMeta.newMapsQueuedCount || 0}, skipped existing: ${batchMeta.skippedExisting || 0}).`
    }
  }];
}
return deduped;

const expectedHeaders = [
  "Company_Name", "Decision_Maker", "Job_Title", "Verified_Email",
  "Email_Type", "Phone", "LinkedIn_Profile", "Website", "City_State",
  "Ad_Pixels", "Intent_Tier", "Cold_Email_Icebreaker", "Contact_Form_URL", "Instagram_URL"
];

const rawValues = $input.first()?.json?.values;
const currentHeaders = (Array.isArray(rawValues) && Array.isArray(rawValues[0]))
  ? rawValues[0].map(h => String(h || '').trim())
  : [];

if (currentHeaders.length === 0 || currentHeaders.every(h => h === '')) {
  return [{
    json: {
      action: 'WRITE_HEADERS',
      statusMessage: 'Sheet is blank. Writing 14 canonical headers to Row 1.',
      headersToWrite: expectedHeaders
    }
  }];
}

if (expectedHeaders.every(h => currentHeaders.includes(h))) {
  return [{
    json: {
      action: 'PROCEED',
      statusMessage: 'Headers already match all 14 canonical schema columns.',
      headersToWrite: currentHeaders
    }
  }];
}

const normalize = (str) => String(str || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const aliasMap = {
  title: "Company_Name",
  name: "Company_Name",
  company: "Company_Name",
  companyname: "Company_Name",
  website: "Website",
  websiteurl: "Website",
  domain: "Website",
  phone: "Phone",
  phonenumber: "Phone",
  city: "City_State",
  citystate: "City_State"
};
for (const exp of expectedHeaders) {
  aliasMap[normalize(exp)] = exp;
}

const usedCanonical = new Set();
let changed = false;

const updatedHeaders = currentHeaders.map((origH) => {
  const mapped = aliasMap[normalize(origH)];
  if (mapped && !usedCanonical.has(mapped)) {
    usedCanonical.add(mapped);
    if (origH !== mapped) changed = true;
    return mapped;
  }
  return origH;
});

if (!usedCanonical.has("Website")) {
  return [{
    json: {
      action: 'DECLINE',
      statusMessage: '❌ Sheet schema mismatch! Missing core Website/website column.',
      headersToWrite: expectedHeaders
    }
  }];
}

for (const exp of expectedHeaders) {
  if (!usedCanonical.has(exp)) {
    updatedHeaders.push(exp);
    usedCanonical.add(exp);
    changed = true;
  }
}

return [{
  json: {
    action: changed ? 'WRITE_HEADERS' : 'PROCEED',
    statusMessage: 'Renamed original sheet headers in-place and appended missing canonical columns.',
    headersToWrite: updatedHeaders
  }
}];

