const state = $getWorkflowStaticData('global');
if (state.lastSummaryExecId === $execution.id) {
  return [];
}
state.lastSummaryExecId = $execution.id;

const cfg = $('Config').first().json;
const batchMeta = $('Filter, Clamp, & Suppress existing domains').first().json;

if ($('Validate Sheet Schema').isExecuted && $('Validate Sheet Schema').first().json.action === 'DECLINE') {
  const errMsg = $('Validate Sheet Schema').first().json.statusMessage;
  return [{
    json: {
      runMode: batchMeta.runMode || 'both',
      summaryText: `❌ Weekly Lead Run Aborted: ${errMsg}`,
      totalLeads: 0,
      existingSheetEnriched: 0,
      newMapsScrapedAndEnriched: 0,
      verifiedEmails: 0,
      decisionMakers: 0,
      highIntentCount: 0,
      skippedExisting: batchMeta.skippedExisting || 0,
      emailHitRatePct: '0%',
      estCostUsd: '$0.00'
    }
  }];
}

let rows = $input.all().map(i => i.json);
try {
  if ($('Merge: Hold leads until verification').isExecuted) {
    const mergedLeads = $('Merge: Hold leads until verification').all().map(i => i.json);
    if (mergedLeads.length > 0) rows = mergedLeads;
  }
} catch (e) {}

if (rows.length === 1 && (rows[0]._isEmpty || rows[0].maxLeads === 0)) {
  const msg = rows[0].summaryText || `⚠️ Weekly Lead Run [mode=${batchMeta.runMode || 'both'}] (${cfg.category} in ${cfg['location (city; state)']}): 0 domains to enrich (skipped ${batchMeta.skippedExisting || 0} already-enriched domains).`;
  return [{
    json: {
      runMode: batchMeta.runMode || 'both',
      summaryText: msg,
      totalLeads: 0,
      existingSheetEnriched: 0,
      newMapsScrapedAndEnriched: 0,
      verifiedEmails: 0,
      decisionMakers: 0,
      highIntentCount: 0,
      skippedExisting: batchMeta.skippedExisting || 0,
      emailHitRatePct: '0%',
      estCostUsd: '$0.00'
    }
  }];
}

const total = rows.length;
const emails = rows.filter(r => r.Verified_Email && r.Verified_Email.includes('@')).length;
const dms = rows.filter(r => r.Decision_Maker && r.Decision_Maker !== '').length;
const highIntent = rows.filter(r => String(r.Intent_Tier || '').includes('High Intent')).length;
const pct = total > 0 ? Math.round((emails / total) * 100) : 0;

// Calculate PPE cost strictly from unique enriched domains returned by Apify (not fanned-out sheet rows)
const apifyItems = $('Enrich Leads').isExecuted ? $('Enrich Leads').all().map(i => i.json) : [];
const billedDomains = apifyItems.length;
const billedPhones = apifyItems.filter(r => r.Phone && r.Phone !== 'None' && r.Phone !== '').length;
const billedDms = apifyItems.filter(r => r.Decision_Maker && r.Decision_Maker !== 'None' && r.Decision_Maker !== '').length;
const billedEmails = apifyItems.filter(r => r.Verified_Email && r.Verified_Email.includes('@')).length;

const estCost = billedDomains > 0
  ? (0.05 + billedDomains * 0.01 + billedPhones * 0.005 + billedDms * 0.01 + billedEmails * 0.01).toFixed(2)
  : '0.00';

return [{
  json: {
    runMode: batchMeta.runMode || 'both',
    totalLeads: total,
    existingSheetEnriched: batchMeta.existingQueuedCount || 0,
    newMapsScrapedAndEnriched: batchMeta.newMapsQueuedCount || 0,
    verifiedEmails: emails,
    decisionMakers: dms,
    highIntentCount: highIntent,
    skippedExisting: batchMeta.skippedExisting || 0,
    emailHitRatePct: `${pct}%`,
    estCostUsd: `$${estCost}`,
    summaryText: `✅ Weekly Lead Run [mode=${batchMeta.runMode || 'both'}] (${cfg.category} in ${cfg['location (city; state)']}): ${total} sheet rows updated (${batchMeta.existingQueuedCount || 0} existing domains + ${batchMeta.newMapsQueuedCount || 0} new Maps domains), ${dms} decision-makers, ${emails} verified emails (${pct}%), ${highIntent} running ads (~$${estCost} est. PPE cost)${batchMeta.clampNote || ''}.`
  }
}];

const originalLeads = $('Deduplicate, Score Intent & Check Empty').all();
const aiOutputs = $input.all();

const aiByLeadIdx = {};
aiOutputs.forEach((item, idx) => {
  const pIdx = item.pairedItem?.item ?? idx;
  aiByLeadIdx[pIdx] = item.json || {};
});

return originalLeads.map((leadItem, idx) => {
  const aiJson = aiByLeadIdx[idx] || {};
  const rawOutput = typeof aiJson.output === 'string'
    ? aiJson.output
    : (aiJson?.output?.[0]?.content?.[0]?.text || aiJson?.message?.content || aiJson?.text || aiJson?.content || '');
  const aiText = String(rawOutput || '').trim().replace(/^["'“”‘’]+|["'“”‘’]+$/g, '').trim();

  return {
    json: {
      ...leadItem.json,
      Cold_Email_Icebreaker: aiText || leadItem.json.Cold_Email_Icebreaker
    }
  };
});
